CREATE OR REPLACE FUNCTION public.admin_send_refresh_check(p_email text, p_first_name text, p_jobs jsonb, p_idempotency_key text) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE req_id bigint; BEGIN SELECT net.http_post(url := 'https://ipnpugitercjsawupazz.supabase.co/functions/v1/send-transactional-email', headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||(SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'email_queue_service_role_key')), body := jsonb_build_object('templateName','listing-refresh-check','recipientEmail',p_email,'idempotencyKey',p_idempotency_key,'templateData',jsonb_build_object('firstName',p_first_name,'jobs',p_jobs))) INTO req_id; RETURN req_id; END; $$; REVOKE ALL ON FUNCTION public.admin_send_refresh_check(text, text, jsonb, text) FROM PUBLIC; REVOKE ALL ON FUNCTION public.admin_send_refresh_check(text, text, jsonb, text) FROM anon; REVOKE ALL ON FUNCTION public.admin_send_refresh_check(text, text, jsonb, text) FROM authenticated;